<script setup lang="ts">
import {computed,onMounted,reactive,ref,watch} from 'vue';
type Request=(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<any>;
const props=defineProps<{request:Request;readonly:boolean;aiReview?:boolean}>();
const busy=ref(false),error=ref(''),notice=ref(''),status=ref<any>({}),tasks=ref<any[]>([]),sources=ref<any[]>([]),runs=ref<any[]>([]),memberId=ref('');
const form=reactive({taskType:'CUSTOMER_SUMMARY',recordId:'',instructions:'',dataApproved:false,confirmationToken:''});
const preview=ref<any>(null),runKey=ref(''),search=ref(''),sourcePage=ref(1),sourceTotal=ref(0),selected=ref<any>(null),proposal=ref<any>(null),saved=ref(false),evaluations=ref<any[]>([]);
const lead=reactive({name:'',companyName:'',industry:'',source:'',region:'',jobTitle:'',phone:'',email:'',description:'',ownerMemberId:''});
const activity=reactive({customerId:'',opportunityId:null,activityType:'CALL',content:'',occurredAt:''});
const review=reactive({decision:'ACCEPTED',factualScore:3,usefulnessScore:3,notes:''});
const task=computed(()=>tasks.value.find(t=>t.id===form.taskType));
const labels=computed(()=>Object.fromEntries(tasks.value.map(t=>[t.id,t.name])));
const qualityLabels:Record<string,string>={NOT_EVALUATED:'未检查',PASS:'规则检查通过',REVIEW:'需主管复核',BLOCKED:'质量策略阻断'};
const states:Record<string,string>={SUCCEEDED:'已完成',PENDING:'待发送',RUNNING:'处理中',FAILED:'调用失败',BLOCKED:'供应商未就绪',NOT_EVALUATED:'未检查',PASS:'规则检查通过',REVIEW:'需主管复核',ACCEPTED:'已采纳',REJECTED:'已退回'};
const canDraft=computed(()=>selected.value?.memberId===memberId.value&&['NEW_LEAD','FOLLOWUP_DRAFT'].includes(selected.value?.taskType)&&selected.value?.status==='SUCCEEDED'&&selected.value?.reviewStatus!=='REJECTED'&&(selected.value?.qualityStatus==='PASS'||selected.value?.qualityStatus==='REVIEW'&&selected.value?.reviewStatus==='ACCEPTED'));
function date(v:string){return v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}):'—';}
function money(v:number){return '¥'+((v||0)/100).toFixed(2);}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
async function options(){const type=form.taskType;const data=await props.request(`/ai/tasks/${type}/sources?page=${sourcePage.value}&pageSize=100&q=${encodeURIComponent(search.value)}`);if(type!==form.taskType)return;sources.value=data.items??[];sourceTotal.value=data.total??sources.value.length;form.recordId=sources.value[0]?.id??'';}
async function refresh(){const catalog=await props.request('/ai/tasks');tasks.value=catalog.items;memberId.value=catalog.memberId;[status.value,runs.value]=await Promise.all([props.request('/ai/status'),props.request('/ai/runs')]);if(selected.value){selected.value=runs.value.find(r=>r.id===selected.value.id)??null;if(!selected.value){proposal.value=null;return;}draftVersion.value=selected.value.proposalVersion??0;saved.value=['APPLIED','CANCELLED'].includes(selected.value.proposalStatus);if(proposal.value&&proposal.value.version!==draftVersion.value)proposal.value=null;}}
async function load(){const catalog=await props.request('/ai/tasks');tasks.value=catalog.items;memberId.value=catalog.memberId;if(!tasks.value.some(t=>t.id===form.taskType))form.taskType=tasks.value[0]?.id??'';await refresh();if(form.taskType)await options();}
function invalidate(){preview.value=null;runKey.value='';form.confirmationToken='';form.dataApproved=false;}
watch(()=>[form.taskType,form.recordId,form.instructions],invalidate);
watch(()=>form.taskType,async()=>{search.value='';sourcePage.value=1;sources.value=[];form.recordId='';if(!busy.value)await run(options);});
async function prepare(){await run(async()=>{preview.value=await props.request('/ai/preview','POST',{...form,dataApproved:false,confirmationToken:null});form.confirmationToken=preview.value.confirmationToken;runKey.value=crypto.randomUUID();});}
async function generate(){await run(async()=>{const result=await props.request('/ai/runs','POST',form,{'Idempotency-Key':runKey.value});await refresh();invalidate();open(result);notice.value=result.status==='SUCCEEDED'?'建议已生成，请核对来源、质量检查和待确认事项。':'本次状态已记录；同一请求重试不会重复外呼。';});}
function suggestions(text:string){try{const raw=text.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');const value=JSON.parse(raw);return value&&typeof value==='object'&&!Array.isArray(value)?value:{};}catch{return {};}}
function open(row:any){selected.value=row;proposal.value=null;saved.value=['APPLIED','CANCELLED'].includes(row.proposalStatus);draftVersion.value=row.proposalVersion??0;evaluations.value=[];review.notes='';const values=suggestions(row.resultText||'');Object.assign(lead,{name:'',companyName:'',industry:'',source:'',region:'',jobTitle:'',phone:'',email:'',description:'',ownerMemberId:memberId.value});for(const key of ['name','companyName','industry','source','region','jobTitle','description'] as const)if(typeof values[key]==='string')lead[key]=values[key].slice(0,key==='description'?4000:key==='companyName'?200:100);Object.assign(activity,{customerId:row.entityId,opportunityId:null,activityType:'CALL',content:typeof values.content==='string'?values.content.slice(0,4000):'',occurredAt:''});}
watch(()=>[JSON.stringify(lead),JSON.stringify(activity)],()=>{proposal.value=null;});
async function prepareDraft(){await run(async()=>{const body=selected.value.taskType==='NEW_LEAD'?{lead:{...lead},activity:null}:{lead:null,activity:{...activity,occurredAt:new Date(activity.occurredAt).toISOString()}};proposal.value=await props.request(`/ai/runs/${selected.value.id}/proposals`,'POST',{...body,expectedVersion:proposal.value?.version??draftVersion.value});draftVersion.value=proposal.value.version;notice.value='已生成保存预览，尚未创建业务记录。请核对后确认。';});}
const draftVersion=ref(0);
async function confirmDraft(){await run(async()=>{const result=await props.request(`/ai/proposals/${proposal.value.id}/confirm`,'POST',{confirmationToken:proposal.value.confirmationToken,expectedVersion:proposal.value.version});saved.value=true;notice.value=`已保存${selected.value.taskType==='NEW_LEAD'?'线索':'跟进记录'}，编号 ${result.resultId}。可从左侧业务导航查看。`;});}
async function cancelDraft(){await run(async()=>{await props.request(`/ai/proposals/${proposal.value.id}/cancel?expectedVersion=${proposal.value.version}`,'POST');proposal.value=null;saved.value=true;notice.value='草稿已取消，本次生成不会再保存业务记录。';});}
async function submitReview(){await run(async()=>{await props.request(`/ai/runs/${selected.value.id}/review`,'POST',{...review,expectedVersion:selected.value.reviewVersion});await refresh();evaluations.value=await props.request(`/ai/runs/${selected.value.id}/evaluations`);notice.value='主管复核与质量评分已记录。';});}
async function historyReview(){await run(async()=>{evaluations.value=await props.request(`/ai/runs/${selected.value.id}/evaluations`);});}
async function feedback(row:any,rating:number){await run(async()=>{await props.request(`/ai/runs/${row.id}/feedback`,'PUT',{rating,notes:''});await refresh();notice.value='使用反馈已保存。';});}
onMounted(()=>run(load));
</script>

<template>
 <section class="p8-assist">
  <div class="page-heading"><div><span class="eyebrow">AI · WORKSPACE</span><h1>AI 业务助手</h1><p>基于当前可见资料生成建议；线索与跟进草稿经编辑、确认后保存。</p></div><button class="btn secondary" :disabled="busy" @click="run(refresh)">刷新记录</button></div>
  <div v-if="error" class="message bad" role="alert">{{error}}</div><div v-if="notice" class="message good" role="status">{{notice}}</div>
  <div class="metrics"><article class="card"><span>供应商</span><strong>{{status.configured?status.provider:'待配置'}}</strong><small>{{status.model||'等待产品方配置 DeepSeek 密钥及模型'}}</small></article><article class="card"><span>本月调用</span><strong>{{status.monthlyUsed||0}} / {{status.monthlyLimit||0}}</strong><small>已用 Token {{status.usage?.usedTokens||0}}</small></article><article class="card"><span>参考费用</span><strong>{{money(status.usage?.estimatedCostCents)}} / {{money(status.monthlyBudgetCents)}}</strong><small>实际费用以供应商账单为准</small></article></div>
  <form class="card panel" @submit.prevent="prepare">
   <h2>选择 AI 场景</h2><div class="fields"><label>AI 场景<select aria-label="AI 场景" v-model="form.taskType" :disabled="busy||readonly"><option v-for="t in tasks" :key="t.id" :value="t.id">{{t.name}}{{t.available?'':' · 待开放'}}</option></select></label><label>业务记录<select aria-label="业务记录" v-model="form.recordId" required :disabled="busy||readonly"><option value="" disabled>请选择业务记录</option><option v-for="o in sources" :key="o.id" :value="o.id">{{o.name}}</option></select></label></div>
   <div v-if="task?.entityType!=='WORKSPACE'" class="source-search"><label>搜索来源资料<input v-model="search" maxlength="100" :disabled="busy"/></label><button type="button" class="btn secondary" :disabled="busy" @click="sourcePage=1;run(options)">搜索</button><button type="button" class="text-button" :disabled="busy||sourcePage<=1" @click="sourcePage--;run(options)">上一页</button><span>第 {{sourcePage}} 页</span><button type="button" class="text-button" :disabled="busy||sourcePage*100>=sourceTotal" @click="sourcePage++;run(options)">下一页</button></div>
   <label class="full">补充要求与事实素材<textarea v-model="form.instructions" maxlength="1000" rows="4" :disabled="busy||readonly" :placeholder="form.taskType==='NEW_LEAD'?'例如：帮我新建李四的线索，公司是星河制造，行业为制造业，来源是展会。缺失必填项将在保存前补全。':'填写已核实的沟通内容、目标或待分析问题。不要填入密码或密钥。'"/></label>
   <p v-if="!task?.available" class="hint">此场景尚未向当前企业开放，请由产品方在“AI 模型与预算 → 提示词与灰度发布”中配置。</p><p v-if="!sources.length" class="hint">没有可读取的业务记录，请先创建记录或确认该模块权限。</p>
   <button class="btn secondary" :disabled="busy||readonly||!form.recordId||!task?.available">预览脱敏内容</button>
   <div v-if="preview" class="preview"><h3>本次发送内容</h3><small>{{preview.provider}} · {{preview.model}} · 确认有效期 5 分钟</small><pre>{{preview.promptPreview}}</pre><label class="check"><input v-model="form.dataApproved" type="checkbox" :disabled="busy||readonly"/>已核对上述内容，同意本次发送给已配置的供应商。</label><button type="button" class="btn primary" :disabled="busy||readonly||!form.dataApproved" @click="generate">{{busy?'处理中…':'确认发送并生成建议'}}</button></div>
  </form>
  <section v-if="selected" class="card panel detail"><div class="title"><h2>{{labels[selected.taskType]||selected.taskType}} · 结果与人工处理</h2><button class="text-button" @click="selected=null">关闭结果</button></div><p>来源：{{selected.contextPreview}} · 提示词 {{selected.promptVersionId?.slice(-6)||'历史版本'}}</p><p class="hint">{{qualityLabels[selected.qualityStatus]||selected.qualityStatus}} · {{states[selected.reviewStatus]||selected.reviewStatus}}。规则检查只能识别部分问题，使用前仍需核对事实。</p><ul v-if="selected.qualityFindings?.length"><li v-for="finding in selected.qualityFindings" :key="finding">{{finding}}</li></ul><pre>{{selected.resultText||states[selected.status]}}</pre>
   <form v-if="canDraft&&!saved" class="draft" @submit.prevent="prepareDraft"><h3>编辑业务草稿</h3><p class="hint">AI 提取的字段需要逐项核对；缺失内容请自行补全。以下编辑不会再发送给模型。</p><div v-if="selected.taskType==='NEW_LEAD'" class="fields"><label>姓名<input v-model="lead.name" required maxlength="100" :disabled="busy||readonly"/></label><label>公司名称<input v-model="lead.companyName" required maxlength="200" :disabled="busy||readonly"/></label><label>行业<input v-model="lead.industry" required maxlength="80" :disabled="busy||readonly"/></label><label>来源<input v-model="lead.source" required maxlength="80" :disabled="busy||readonly"/></label><label>地区<input v-model="lead.region" maxlength="100" :disabled="busy||readonly"/></label><label>职位<input v-model="lead.jobTitle" maxlength="100" :disabled="busy||readonly"/></label><label>电话（人工填写，可留空）<input v-model="lead.phone" maxlength="40" :disabled="busy||readonly"/></label><label>邮箱（人工填写，可留空）<input v-model="lead.email" type="email" maxlength="254" :disabled="busy||readonly"/></label><label class="wide">线索备注<textarea v-model="lead.description" maxlength="4000" :disabled="busy||readonly"/></label></div><div v-else class="fields"><label>互动方式<select v-model="activity.activityType" :disabled="busy||readonly"><option value="CALL">电话</option><option value="VISIT">拜访</option><option value="MEETING">会议</option><option value="EMAIL">邮件</option><option value="OTHER">其他</option></select></label><label>实际发生时间<input v-model="activity.occurredAt" type="datetime-local" required :disabled="busy||readonly"/></label><label class="wide">已核实的跟进内容<textarea v-model="activity.content" maxlength="4000" rows="5" required :disabled="busy||readonly"/></label></div><button class="btn secondary" :disabled="busy||readonly">预览业务保存</button>
   <div v-if="proposal" class="preview"><h3>业务保存确认</h3><pre>{{JSON.stringify(proposal.payload,null,2)}}</pre><p>保存后可在{{selected.taskType==='NEW_LEAD'?'“线索”':'“跟进记录”'}}查看；同一生成记录只保存一次。</p><button type="button" class="btn primary" :disabled="busy||readonly" @click="confirmDraft">确认保存{{selected.taskType==='NEW_LEAD'?'线索':'跟进记录'}}</button><button type="button" class="btn secondary" :disabled="busy||readonly" @click="cancelDraft">取消此草稿</button></div></form>
   <form v-if="aiReview&&selected.status==='SUCCEEDED'" class="draft" @submit.prevent="submitReview"><h3>主管复核与质量评分</h3><div class="fields"><label>复核结论<select v-model="review.decision" :disabled="busy||readonly"><option value="ACCEPTED">核对后采纳</option><option value="REJECTED">退回</option></select></label><label>事实准确度（1–5）<input v-model.number="review.factualScore" type="number" min="1" max="5" required :disabled="busy||readonly"/></label><label>业务帮助度（1–5）<input v-model.number="review.usefulnessScore" type="number" min="1" max="5" required :disabled="busy||readonly"/></label><label>核实依据<textarea v-model="review.notes" minlength="10" maxlength="1000" required :disabled="busy||readonly"/></label></div><button class="btn secondary" :disabled="busy||readonly||selected.qualityStatus==='BLOCKED'&&review.decision==='ACCEPTED'">保存复核</button></form>
   <button class="text-button" :disabled="busy" @click="historyReview">查看复核历史</button><div v-for="e in evaluations" :key="e.id" class="evaluation"><strong>{{e.reviewerName}} · {{states[e.decision]}} · {{date(e.createdAt)}}</strong><p>事实 {{e.factualScore}} / 5 · 帮助度 {{e.usefulnessScore}} / 5 · {{e.notes}}</p></div>
  </section>
  <section class="card panel"><h2>调用记录</h2><p class="hint">仅显示当前仍有业务读取权限的记录。AI 生成不会发送邮件、修改审批、合同或回款。</p><div class="table-scroll"><table><thead><tr><th>场景 / 时间</th><th>来源 / 发起人</th><th>结果 / 质量</th><th>Token / 参考费用</th><th>操作</th></tr></thead><tbody><tr v-for="row in runs" :key="row.id"><td>{{labels[row.taskType]||row.taskType}}<small>{{date(row.createdAt)}}</small></td><td>{{row.contextPreview}}<small>{{row.memberName}}</small></td><td>{{states[row.status]}}<small>{{qualityLabels[row.qualityStatus]}} · {{states[row.reviewStatus]}}</small></td><td>{{row.inputTokens+row.outputTokens}}<small>{{money(row.estimatedCostCents)}}{{row.usageEstimated?' · 保守估算':''}}</small></td><td><button class="text-button" @click="open(row)">查看与处理</button><button v-if="row.status==='SUCCEEDED'" class="text-button" :disabled="busy||readonly" @click="feedback(row,1)">有帮助</button><button v-if="row.status==='SUCCEEDED'" class="text-button" :disabled="busy||readonly" @click="feedback(row,-1)">需改进</button></td></tr><tr v-if="!runs.length"><td colspan="5">暂无调用记录。先选择场景和来源资料。</td></tr></tbody></table></div></section>
 </section>
</template>

<style scoped>
.p8-assist{display:flex;flex-direction:column;gap:20px;min-width:0;color:var(--text-primary,#e0ebff)}.panel{padding:24px;min-width:0}.panel h2{font-size:18px;margin-bottom:16px}.panel h3{font-size:15px;margin:12px 0}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.metrics article{padding:22px;display:flex;flex-direction:column;gap:10px}.metrics strong{font-size:22px}.metrics span,.hint,small,.panel p{color:var(--text-muted,#9bacc6);font-size:12px;line-height:1.8}.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:16px 0}label{display:flex;flex-direction:column;gap:8px;font-size:13px;min-width:0}input,select,textarea{width:100%;box-sizing:border-box;padding:11px;border:1px solid rgba(142,171,216,.3);border-radius:8px;background:rgba(5,14,29,.65);color:inherit;font:inherit}.wide{grid-column:1/-1}.full{margin:18px 0}.check{flex-direction:row;align-items:flex-start;margin:14px 0}.check input{width:auto;margin-top:4px}.preview,.draft{margin-top:20px;padding-top:18px;border-top:1px solid rgba(142,171,216,.25)}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:360px;overflow:auto;font:inherit;font-size:12px;line-height:1.9;background:rgba(6,16,34,.4);padding:16px;border-radius:8px}.message{padding:14px 18px;border:1px solid #3d6087;border-radius:8px;font-size:13px;line-height:1.8}.bad{border-color:#c26578;color:#ffbac6}.good{border-color:#458983;color:#a8eddf}.title,.source-search{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.title{justify-content:space-between}.source-search{margin-top:14px;font-size:12px}.source-search label{flex:1;min-width:180px}td{vertical-align:top;max-width:300px;overflow-wrap:anywhere}td small{display:block;margin-top:6px}.evaluation{padding:12px 0;border-bottom:1px solid #30435c;font-size:12px}.btn+.btn{margin-left:10px}li{font-size:12px;color:#f3c788}@media(max-width:800px){.metrics,.fields{grid-template-columns:1fr}.wide{grid-column:auto}.panel{padding:16px}.metrics{gap:10px}.metrics strong{font-size:20px}.page-heading{flex-wrap:wrap}.source-search label{min-width:100%}}
</style>
